class Solution:
    def longestConsecutive(self, nums: List[int]) -> int:
        seen = set(nums)
        best = 0
        for x in seen:
            if x - 1 not in seen:             # only start counting at the beginning of a run
                length = 1
                while x + length in seen:
                    length += 1
                best = max(best, length)
        return best
